class Solution {
    private class Pair{
        String sb;
        int k;
        Pair(){}
        Pair(String sb,int k){
            this.sb = sb;
            this.k = k;
        }
    }
    public String decodeString(String s) {
        char[]arr = s.toCharArray();
        Stack<Pair> stack = new Stack<>();
        StringBuilder res = new StringBuilder();
        int k = 0;
        for(int i = 0;i<arr.length;i++){
            if(Character.isDigit(arr[i])){
                k = k*10 + arr[i]-'0';
            }else if(Character.isLetter(arr[i])){
                res.append(arr[i]);
            }else if(arr[i]=='['){
                stack.push(new Pair(res.toString(),k));
                k = 0;
                res.setLength(0);
            }else{
                Pair item = stack.pop();
                StringBuilder temp = new StringBuilder(item.sb);
                for(int j = 0;j<item.k;j++){
                    temp.append(res);
                }
                res = temp;
            }
        }
        return res.toString();
    }
}
